// @ts-nocheck -- desktop bridge additions are generated by Electron preload.
import {ScreenSharingPanel} from './ScreenSharing';
import {useI18n} from './i18n';
import {useEffect,useState} from 'react';
import {RemoteQrDialog} from './RemoteQrDialog';
import {useLiveAnnotations} from './LiveAnnotations';

export interface PersonalMonitor{id:string;slug:string;name:string;sourceType:'main'|'stage'|'livestream';layout:'mirror'|'current-next';defaultLanguage:'de'|'en';showCurrent:boolean;showNext:boolean;showClock:boolean;showCountdown:boolean;showNotes:boolean;showOrderOfService:boolean;enabled:boolean;token:string;connected?:number}
export interface RemoteDevice{id:string;name:string;permissionRole:'view'|'preacher'|'control'|'advanced';preferredLanguage:'de'|'en';permissions:string[];token:string;revoked:boolean;lastSeenAt?:string}
export interface RemoteServiceState{active:boolean;address:string;securePort?:number;fingerprint?:string;monitors:PersonalMonitor[];remotes:RemoteDevice[]}
const empty:RemoteServiceState={active:false,address:'127.0.0.1',monitors:[],remotes:[]};
const rolePermissions:Record<RemoteDevice['permissionRole'],string[]>={view:['remote.view'],preacher:['remote.view','remote.viewNotes'],control:['remote.view','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen'],advanced:['remote.view','remote.viewNotes','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen','remote.stageMessage','remote.viewRecording']};

export function RemoteCenter(){
  const {t,tx}=useI18n();
  const [state,setState]=useState(empty),[mode,setMode]=useState<'overview'|'monitor'|'remote'>('overview'),[name,setName]=useState('Prediger Monitor'),[slug,setSlug]=useState('prediger'),[source,setSource]=useState<PersonalMonitor['sourceType']>('stage'),[role,setRole]=useState<RemoteDevice['permissionRole']>('preacher'),[language,setLanguage]=useState<'de'|'en'>('de');
  const [qr,setQr]=useState<{name:string;url:string}|null>(null);
  const [allowSharing,setAllowSharing]=useState(false),[allowAnnotations,setAllowAnnotations]=useState(false),[layout,setLayout]=useState<PersonalMonitor['layout']>('current-next'),[showNotes,setShowNotes]=useState(false),[showOrder,setShowOrder]=useState(false);
  const refresh=()=>window.desktop?.remote.get().then(setState).catch(()=>setState(empty));
  useEffect(()=>{void refresh();const timer=setInterval(refresh,3000);return()=>clearInterval(timer)},[]);
  const base=state.securePort?`https://${state.address}:${state.securePort}`:null;
  async function addMonitor(){await window.desktop?.remote.saveMonitor({id:crypto.randomUUID(),slug:slug.toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/^-+|-+$/g,''),name,sourceType:source,layout,defaultLanguage:language,showCurrent:true,showNext:true,showClock:true,showCountdown:true,showNotes,showOrderOfService:showOrder,enabled:true});setMode('overview');refresh()}
  async function addRemote(){if(!base)return;const result=await window.desktop?.remote.createSession({name,permissionRole:role,preferredLanguage:language,permissions:[...rolePermissions[role],...(allowAnnotations?['remote.annotate']:[]),...(allowSharing?['remote.share']:[])]});setMode('overview');await refresh();if(result)setQr({name:result.name,url:`${base}/remote/${result.token}`})}
  const copy=(value:string)=>void navigator.clipboard.writeText(value);
  return <><section className="remote-center"><h3>{tx("Anzeige & Web-Steuerung")}</h3><p>{tx("Personal Monitore sind dauerhaft erreichbare, reine Anzeigen. Web-Steuerungen erhalten eine individuelle widerrufbare Sitzung und nur ausdrücklich freigegebene Befehle.")}</p><div className={`remote-service ${state.active?'online':'offline'}`}><span/><div><b>{state.active?tx("Remote-Service bereit"):tx("Remote-Service nicht verfügbar")}</b><small>{base??'HTTPS'} {" "}{tx("· lokales Netzwerk")}</small></div><button onClick={refresh}>{tx("Status prüfen")}</button></div>{state.securePort&&<div><p>{t('remoteVerifyCertificate')}<small>{tx("Zertifikat-Fingerabdruck")}: {state.fingerprint}</small></p><button onClick={()=>void window.desktop?.remote.exportCertificate()}>{t('remoteExportCertificate')}</button></div>}{mode==='overview'?<><div className="remote-actions"><button className="primary" disabled={!base} onClick={()=>{setName('Prediger Monitor');setSlug('prediger');setMode('monitor')}}>{tx("+ Personal Monitor")}</button><button disabled={!base} onClick={()=>{setName('iPad Prediger');setAllowAnnotations(false);setAllowSharing(false);setMode('remote')}}>{tx("+ Gerät verbinden")}</button></div><h4>{tx("Personal Monitore")}</h4><div className="remote-list">{state.monitors.map(m=><article key={m.id}><span className="material-symbols-outlined">monitor</span><div><b>{m.name}</b><small>{m.sourceType.toUpperCase()} · {m.slug} · {m.connected??0} {" "}{tx("verbunden")}</small></div><button disabled={!base} onClick={()=>copy(`${base}/monitor/${m.token}`)}>{tx("URL kopieren")}</button><button disabled={!base} onClick={()=>setQr({name:m.name,url:`${base}/monitor/${m.token}`})}>{tx("QR-CODE")}</button><button disabled={!base} onClick={()=>void window.desktop?.openExternal(`${base}/monitor/${m.token}`)}>{tx("Vorschau")}</button><button className="danger" onClick={async()=>{if(confirm(tx("Personal Monitor „{value1}“ deaktivieren?",{value1:(m.name)}))){await window.desktop?.remote.removeMonitor(m.id);refresh()}}}>{tx("Deaktivieren")}</button></article>)||null}{!state.monitors.length&&<p>{tx("Noch kein Personal Monitor eingerichtet.")}</p>}</div><button onClick={()=>{useLiveAnnotations.setState({state:null});void window.desktop?.sendAnnotations?.(null)}}>{tx("Live-Markierungen löschen")}</button><ScreenSharingPanel/><h4>{tx("Web-Steuerungen")}</h4><div className="remote-list">{state.remotes.filter(r=>!r.revoked).map(r=><article key={r.id}><span className="material-symbols-outlined">phone_iphone</span><div><b>{r.name}</b><small>{r.permissionRole.toUpperCase()} · {r.preferredLanguage==='de'?tx("Deutsch"):'English'} {" "}{tx("· sichere Einzelsitzung")}</small></div><button disabled={!base} onClick={()=>copy(`${base}/remote/${r.token}`)}>{tx("URL kopieren")}</button><button disabled={!base} onClick={()=>setQr({name:r.name,url:`${base}/remote/${r.token}`})}>{tx("QR-CODE")}</button><button className="danger" onClick={async()=>{await window.desktop?.remote.revokeSession(r.id);refresh()}}>{tx("Zugriff widerrufen")}</button></article>)}{!state.remotes.some(r=>!r.revoked)&&<p>{tx("Noch keine Web-Steuerung freigegeben.")}</p>}</div></>:mode==='monitor'?<div className="remote-form"><h4>{tx("Personal Monitor erstellen")}</h4><label>{tx("Name")}<input value={name} onChange={e=>setName(e.target.value)}/></label><label>{tx("URL-Kennung")}<input value={slug} onChange={e=>setSlug(e.target.value)}/><small>{tx("Die URL bleibt bei Gottesdienst-, Benutzer- und Programmwechsel gleich.")}</small></label><label>{tx("Ansicht")}<select value={layout} onChange={e=>setLayout(e.target.value)}><option value="current-next">{tx("Aktuelle und nächste Folie")}</option><option value="mirror">{tx("Große aktuelle Folie")}</option></select></label><label><input type="checkbox" checked={showNotes} onChange={e=>setShowNotes(e.target.checked)}/>{tx("Notizen anzeigen")}</label><label><input type="checkbox" checked={showOrder} onChange={e=>setShowOrder(e.target.checked)}/>{tx("Ablauf anzeigen")}</label><label>{tx("Quelle")}<select value={source} onChange={e=>setSource(e.target.value as PersonalMonitor['sourceType'])}><option value="stage">{tx("STAGE – Prediger")}</option><option value="main">{tx("MAIN")}</option><option value="livestream">LIVESTREAM</option></select></label><label>{tx("Sprache")}<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">{tx("Deutsch")}</option><option value="en">English</option></select></label><footer><button onClick={()=>setMode('overview')}>{tx("Abbrechen")}</button><button className="primary" disabled={!base||!name.trim()||!slug.trim()} onClick={()=>void addMonitor()}>{tx("ERSTELLEN")}</button></footer></div>:<div className="remote-form"><h4>{tx("Web-Steuerung freigeben")}</h4><label>{tx("Gerätename")}<input value={name} onChange={e=>setName(e.target.value)}/></label><label>{tx("Berechtigung")}<select value={role} onChange={e=>setRole(e.target.value as RemoteDevice['permissionRole'])}><option value="view">{tx("Nur Anzeige")}</option><option value="preacher">{tx("Prediger")}</option><option value="control">{tx("Steuerung")}</option><option value="advanced">{tx("Erweiterte Steuerung")}</option></select></label><label>{tx("Sprache")}<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">{tx("Deutsch")}</option><option value="en">English</option></select></label><label><input type="checkbox" checked={allowAnnotations} onChange={e=>setAllowAnnotations(e.target.checked)}/>{tx("Live-Markierungen auf allen Ausgaben erlauben")}</label><label><input type="checkbox" checked={allowSharing} onChange={e=>setAllowSharing(e.target.checked)} disabled={!state.securePort}/>{tx("Bildschirmfreigabe für dieses Gerät erlauben")}</label><p>{tx("Das verbundene Gerät wählt seinen Bildschirm oder ein Fenster. Die Regie sieht zuerst eine Vorschau und übernimmt sie bewusst auf MAIN.")}</p><p>{tx("Markierungen erscheinen auch auf MAIN. Ein reiner Monitor-Link bleibt schreibgeschützt. Nach dem Erstellen erscheint ein QR-Code. ON AIR/OFF AIR bleibt der Regie vorbehalten.")}</p><footer><button onClick={()=>setMode('overview')}>{tx("Abbrechen")}</button><button className="primary" disabled={!base||!name.trim()} onClick={()=>void addRemote()}>{tx("Verbindung starten")}</button></footer></div>}</section>{qr&&<RemoteQrDialog {...qr} onClose={()=>setQr(null)}/>}</>
}
